import { afterEach, describe, expect, it, vi } from 'vitest';
import {
  buildEncryptedParams,
  buildStreamParams,
  clientSign,
  decryptResponse,
  healthHost,
  isXiaomiLongPollUrl,
  listFitnessDevices,
  parseSourceList,
  pollQrLogin,
  rc4,
  Session,
  signedNonce,
  ssoSession,
  startQrLogin,
} from '../worker/xiaomi-cloud';

// Expected values generated by the functions of token_extractor.py (generate_enc_params /
// encrypt_rc4) with fixed inputs.
const SSECURITY = 'c3NlY3VyaXR5LXRlc3QtdmFsdWU=';
const NONCE = 'AAECAwQFBgcAAQID';

describe('xiaomi cloud request signing', () => {
  it('matches token_extractor.py generate_enc_params', async () => {
    const params = await buildEncryptedParams('/v2/homeroom/gethome', '{"fg": true, "fetch_share": true}', SSECURITY, NONCE);
    expect(params).toEqual([
      ['data', '/xDmSesBHg85H7usewGg+cR2WLdqFBk4Wolx039dtHeo'],
      ['rc4_hash__', '9QXQdL51CUN9DI+xM1SEt/dQabJ6DCg4ZsVzzg=='],
      ['signature', 'JZ0emAb8U3Z+6jp0eXK9u60Hz+8='],
      ['ssecurity', SSECURITY],
      ['_nonce', NONCE],
    ]);
  });

  it('decrypts an RC4 response', async () => {
    expect(await decryptResponse(SSECURITY, NONCE, '/xDjQa1eHEF7RvzyPlCz8MQ3CpM7ExNoBZo2jg==')).toBe('{"code":0,"result":{"ok":1}}');
  });

  it('only proxies Xiaomi long-polling URLs', () => {
    expect(isXiaomiLongPollUrl('https://sgp.lp.account.xiaomi.com/lp/s?k=lp_96D43D0116fa57')).toBe(true); // real shape
    expect(isXiaomiLongPollUrl('https://account.xiaomi.com/longPolling/login?ticket=1')).toBe(true);
    expect(isXiaomiLongPollUrl('https://c3.account.xiaomi.com/longPolling/login?ticket=1')).toBe(true);
    expect(isXiaomiLongPollUrl('https://evil.example/longPolling/')).toBe(false);
    expect(isXiaomiLongPollUrl('https://account.xiaomi.com.evil.example/longPolling/')).toBe(false);
    expect(isXiaomiLongPollUrl('http://account.xiaomi.com/longPolling/')).toBe(false);
    expect(isXiaomiLongPollUrl('https://account.xiaomi.com/pass/serviceLogin')).toBe(false);
  });
});

// ---------------------------------------------------------------- Mi Fitness ---


const b64 = (u: Uint8Array) => btoa(String.fromCharCode(...u));
const unb64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
async function encryptBody(ssecurity: string, nonce: string, body: unknown): Promise<string> {
  return b64(rc4(unb64(await signedNonce(ssecurity, nonce)), new TextEncoder().encode(JSON.stringify(body))));
}

// Synthetic get_source_list answer, shaped like the records read by AstroBox (detail.encrypt_key)
// and huami-token (detail.auth_key, detail sometimes a JSON string). No real account data.
const SOURCE_LIST = {
  code: 0,
  message: 'ok',
  result: {
    list: [
      {
        sid: 'x',
        identifier: '123456',
        name: 'Xiaomi Smart Band 9 ',
        model: 'miwear.watch.n67cn',
        status: 1,
        detail: { mac: 'AA:BB:CC:DD:EE:FF', encrypt_key: '00112233445566778899aabbccddeeff', token: '00112233445566778899AABBCCDDEEFF', beaconkey: 'ffeeddccbbaa99887766554433221100' },
      },
      { name: 'Band 7', model: 'm7', identifier: '7', detail: JSON.stringify({ mac: '11:22:33:44:55:66', auth_key: '0xa3c10e34e5c14637eea6b9efc0610600' }) },
      { name: 'Watch', model: 'w', identifier: '8', detail: { mac: '01:02:03:04:05:06', encrypt_key: 'short', token: 'abcdefabcdefabcdefabcdefabcdefab' } },
      { name: 'Scale', model: 's', identifier: '9', detail: { mac: '0A:0B:0C:0D:0E:0F' } },
    ],
  },
};

describe('mi fitness request signing', () => {
  it('matches huami-token mi_encrypt_params (continuous RC4 stream)', async () => {
    const p = await buildStreamParams('/app/v1/source/get_source_list', { data: '{"page_size":50,"status":1}' }, SSECURITY, NONCE);
    expect(Object.fromEntries(p)).toEqual({
      data: '/xDwT65eYQgiELuiYRb2sJJmRIltCQtoBZo2',
      rc4_hash__: 'wD5uslCzL6uwNG10EVHFyEgnbuF19XFg6sZfww==',
      signature: 'gkpR/qHCiz+by9zd7GGaBHJtPeA=',
      _nonce: NONCE,
    });
  });

  it('decrypts a response encrypted by huami-token', async () => {
    const body =
      '';
    const parsed = JSON.parse(await decryptResponse(SSECURITY, NONCE, body));
    expect(parsed.result.list[0].detail.encrypt_key).toBe('00112233445566778899aabbccddeeff');
  });

  it('computes clientSign like huami-token', async () => {
    // base64(SHA1("nonce=123&<ssecurity>")) computed with Python hashlib
    expect(await clientSign('123', SSECURITY)).toBe('FQOy1e1ntVXrQpv0QbLHtldZT2U=');
  });

  it('only builds hostnames from known regions', () => {
    expect(healthHost()).toBe('hlth.io.mi.com');
    expect(healthHost('cn')).toBe('hlth.io.mi.com');
    expect(healthHost('sg')).toBe('sg.hlth.io.mi.com');
    expect(healthHost('evil.example/#')).toBe('hlth.io.mi.com');
  });
});

describe('parseSourceList', () => {
  const rows = parseSourceList(SOURCE_LIST, 'hlth.io.mi.com');

  it('keeps one row per distinct valid key, best field first', () => {
    expect(rows.filter((r) => r.name === 'Xiaomi Smart Band 9')).toEqual([
      { server: 'hlth.io.mi.com', source: 'mifitness', name: 'Xiaomi Smart Band 9', model: 'miwear.watch.n67cn', did: '123456', mac: 'AA:BB:CC:DD:EE:FF', key: '00112233445566778899aabbccddeeff', keyField: 'encrypt_key' },
    ]);
  });

  it('reads a JSON-string detail and strips 0x', () => {
    expect(rows.find((r) => r.name === 'Band 7')).toMatchObject({ key: 'a3c10e34e5c14637eea6b9efc0610600', keyField: 'auth_key', mac: '11:22:33:44:55:66' });
  });

  it('skips malformed keys and never offers a beacon key', () => {
    expect(rows.filter((r) => r.name === 'Watch').map((r) => r.keyField)).toEqual(['token']);
    expect(rows.some((r) => r.key === 'ffeeddccbbaa99887766554433221100')).toBe(false);
  });

  it('lists devices without a key so the page can say so', () => {
    const scale = rows.find((r) => r.name === 'Scale')!;
    expect(scale.mac).toBe('0A:0B:0C:0D:0E:0F');
    expect(scale.key).toBeUndefined();
    expect(parseSourceList(null, 'x')).toEqual([]);
    expect(parseSourceList({ code: 0, result: { list: null } }, 'x')).toEqual([]);
  });
});

describe('mi fitness login and listing (mocked Xiaomi)', () => {
  afterEach(() => vi.unstubAllGlobals());

  it('asks for a Mi Fitness (miothealth) QR login', async () => {
    const fetchMock = vi.fn(async (_u: string) => new Response('&&&START&&&{"qr":"https://account.xiaomi.com/pass/qr/login?x","loginUrl":"https://sgp.account.xiaomi.com/longPolling/login?ticket=lp_1","lp":"https://sgp.lp.account.xiaomi.com/lp/s?k=lp_1","timeout":300}'));
    vi.stubGlobal('fetch', fetchMock);
    await startQrLogin();
    const url = new URL(fetchMock.mock.calls[0][0]);
    expect(url.searchParams.get('sid')).toBe('miothealth');
    expect(url.searchParams.get('callback')).toBe('https://sts-hlth.io.mi.com/healthapp/sts');
  });

  it('reads the long-poll answer', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => new Response('&&&START&&&{"userId":1,"cUserId":"c","ssecurity":"' + SSECURITY + '","passToken":"p","location":"https://sts-hlth.io.mi.com/healthapp/sts?x=1","nonce":5}')));
    expect(await pollQrLogin('https://sgp.lp.account.xiaomi.com/lp/s?k=1', 1000)).toEqual({ userId: '1', cUserId: 'c', ssecurity: SSECURITY, passToken: 'p', location: 'https://sts-hlth.io.mi.com/healthapp/sts?x=1', nonce: '5' });
  });

  it('falls back to the stream variant and returns the keys', async () => {
    const calls: string[] = [];
    vi.stubGlobal(
      'fetch',
      vi.fn(async (u: string, init: RequestInit) => {
        const url = new URL(u);
        const variant = url.searchParams.has('_nonce') ? 'mihome' : 'stream';
        calls.push(`${url.host}${url.pathname} ${variant}`);
        if (variant === 'mihome') return new Response('unauthorized', { status: 401 });
        const nonce = new URLSearchParams(String(init.body)).get('_nonce')!;
        return new Response(await encryptBody(SSECURITY, nonce, SOURCE_LIST));
      }),
    );
    const res = await listFitnessDevices(new Session('1', SSECURITY, 'token', 'c'), 'sg', 4);
    expect(calls).toEqual(['hlth.io.mi.com/app/v1/source/get_source_list mihome', 'hlth.io.mi.com/app/v1/source/get_source_list stream']);
    expect(res.ok).toBe(true);
    expect(res.devices.filter((d) => d.key).length).toBe(3);
  });

  it('tries the region host when the base host has no devices', async () => {
    const hosts: string[] = [];
    vi.stubGlobal(
      'fetch',
      vi.fn(async (u: string) => {
        const url = new URL(u);
        hosts.push(url.host);
        const body = url.host === 'sg.hlth.io.mi.com' ? SOURCE_LIST : { code: 0, result: { list: [] } };
        return new Response(await encryptBody(SSECURITY, url.searchParams.get('_nonce')!, body));
      }),
    );
    const res = await listFitnessDevices(new Session('1', SSECURITY, 'token', 'c'), 'sg', 4);
    expect(hosts).toEqual(['hlth.io.mi.com', 'sg.hlth.io.mi.com']);
    expect(res.devices[0].server).toBe('sg.hlth.io.mi.com');
  });

  it('reports not ok when Xiaomi rejects every variant', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => new Response('', { status: 401 })));
    expect(await listFitnessDevices(new Session('1', SSECURITY, 't'), undefined, 4)).toEqual({ ok: false, devices: [] });
  });

  it('signs in to Mi Home with the passToken (no second scan)', async () => {
    const seen: { url: string; cookie?: string }[] = [];
    vi.stubGlobal(
      'fetch',
      vi.fn(async (u: string, init?: RequestInit) => {
        seen.push({ url: u, cookie: (init?.headers as Record<string, string> | undefined)?.Cookie });
        if (u.startsWith('https://account.xiaomi.com/pass/serviceLogin')) {
          return new Response('&&&START&&&{"code":0,"userId":1,"cUserId":"c","ssecurity":"' + SSECURITY + '","location":"https://sts.api.io.mi.com/sts?d=1","nonce":7}');
        }
        return new Response(null, { status: 302, headers: { 'set-cookie': 'serviceToken=abc; path=/' } });
      }),
    );
    const login = { userId: '1', cUserId: 'c', ssecurity: SSECURITY, passToken: 'p', location: 'x' };
    expect(await ssoSession(login, 'xiaomiio')).toBeInstanceOf(Session);
    expect(seen[0].url).toContain('sid=xiaomiio');
    expect(seen[0].cookie).toContain('passToken=p');
    expect(seen[1].url).toMatch(/^https:\/\/sts\.api\.io\.mi\.com\/sts\?d=1&clientSign=/);
  });

  it('gives up on SSO when Xiaomi asks for a new login', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => new Response('&&&START&&&{"code":70016,"_sign":"x"}')));
    expect(await ssoSession({ userId: '1', cUserId: 'c', ssecurity: SSECURITY, passToken: 'p', location: 'x' }, 'xiaomiio')).toBeNull();
  });
});
